@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const d=document.getElementById('documentDrawer'),b=document.getElementById('documentBackdrop'),f=document.getElementById('documentPreviewFrame'),n=document.getElementById('documentPreviewName'),dl=document.getElementById('documentPreviewDownload');function close(){d.classList.remove('open');b.classList.remove('open');f.src='about:blank'}document.querySelectorAll('.js-document-preview').forEach(x=>x.addEventListener('click',function(){n.textContent=this.dataset.documentName;f.src=this.dataset.previewUrl;dl.href=this.dataset.downloadUrl;d.classList.add('open');b.classList.add('open')}));document.getElementById('closeDocumentPreview').addEventListener('click',close);b.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})});</script>@endpush
